import {escapeHTML as e,payload,matches,classify,urls,dateISO,localDate,favoriteKey} from './data.js';
const $=s=>document.querySelector(s);
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
let prefs=read('vl-prefs',{committee:'',group:'',favorites:[]});
if(!Array.isArray(prefs.favorites))prefs.favorites=[];
let tab='live',filter='all',query='',date=localDate(),groups=[],record=null,loading=false,request=0,controller;
const cacheKey=(kind,c=prefs.committee,g=prefs.group)=>`vl-data:${c}:${kind}:${kind==='live'||kind==='groups'?'':g}`;
const savePrefs=()=>write('vl-prefs',prefs);
const empty=(title,text,button='')=>`<div class="empty"><div class="symbol" aria-hidden="true">◉</div><h3>${e(title)}</h3><p>${e(text)}</p>${button}</div>`;
const message=(text,help=false)=>{$('#notice').innerHTML=text?`<div class="notice">${e(text)} ${help?'<button id="notice-help">Apri dati e importazione ↗</button>':''}</div>`:'';$('#notice-help')?.addEventListener('click',openHelp)};
function setConnection(){$('#connection').textContent=navigator.onLine?'Online':'Offline';$('#connection').classList.toggle('offline',!navigator.onLine)}
function updateGroups(){const select=$('#group');select.innerHTML='<option value="">Scegli un girone</option>'+groups.map(g=>`<option value="${e(g.id)}">${e(g.title)}</option>`).join('');select.value=prefs.group;}
async function fetchData(kind,signal){let last;for(const url of urls(kind,prefs.committee,prefs.group)){try{const r=await fetch(url,{credentials:'omit',headers:{Accept:'application/json'},signal});if(!r.ok)throw new Error(`HTTP ${r.status}`);const json=await r.json();if(classify(json)!==kind)throw new Error('Formato dati inatteso');return json}catch(err){if(signal.aborted)throw err;last=err}}throw last}
async function loadGroups(signal){try{const json=await fetchData('groups',signal);if(signal.aborted)return;groups=json.data;write(cacheKey('groups'),{json,at:Date.now(),source:'network'});updateGroups()}catch{if(signal.aborted)return;groups=read(cacheKey('groups'),null)?.json?.data||[];updateGroups()}}
async function load(){
 controller?.abort();controller=new AbortController();const signal=controller.signal,seq=++request;loading=false;$('#refresh').disabled=false;
 record=null;message('');
 $('#group-wrap').hidden=!['calendar','standings'].includes(tab);$('#date-wrap').hidden=tab==='standings'||tab==='favorites';$('#all-dates').hidden=tab==='standings'||tab==='favorites';$('.segmented').hidden=tab==='standings'||tab==='favorites';
 const titles={live:['Dentro la partita.','Risultati e incontri del tuo comitato.','Le gare'],calendar:['Il prossimo servizio.','Tutti gli incontri del girone, giornata dopo giornata.','Calendario'],standings:['La corsa alla vetta.','Punti, vittorie e set del tuo campionato.','Classifica'],favorites:['La tua pallavolo.','Squadre e campionati che vuoi tenere vicini.','I tuoi preferiti']};
 const t=titles[tab];$('#page-title').textContent=t[0];$('#subtitle').textContent=t[1];$('#list-title').textContent=t[2];
 if(tab==='favorites'){render();return}
 if(!prefs.committee){render();return}
 if(tab==='calendar'||tab==='standings'){
  groups=read(cacheKey('groups'),null)?.json?.data||[];updateGroups();
  if(!prefs.group){$('#results').innerHTML=empty('Scegli il tuo girone','Seleziona un girone per vedere '+(tab==='calendar'?'il calendario.':'la classifica.'));$('#updated').textContent='';loading=true;$('#refresh').disabled=true;await loadGroups(signal);if(seq===request){loading=false;$('#refresh').disabled=false;if(!groups.length)message('Elenco gironi non raggiungibile. Puoi importare il JSON dei gironi FIPAV.',true)}return}
 }
 loading=true;$('#refresh').disabled=true;record=read(cacheKey(tab),null);if(record)record={...record,fromCache:true};render();if(!record)$('#results').innerHTML=empty('Un attimo, entriamo in campo…','Caricamento dei dati FIPAV.');
 const timeout=setTimeout(()=>controller?.signal===signal&&controller.abort(),18000);
 try{const json=await fetchData(tab,signal);if(seq!==request)return;record={json,at:Date.now(),source:'network'};if(!write(cacheKey(tab),record))message('Memoria locale piena: i dati sono visibili ma non verranno conservati offline.');}
 catch(err){if(seq!==request)return;message(navigator.onLine?'Dati FIPAV non raggiungibili. L’accesso dal browser può essere bloccato da CORS oppure il servizio non è disponibile.':'Sei offline. Sono disponibili solo i dati già salvati su questo dispositivo.',true)}
 finally{clearTimeout(timeout);if(seq===request){loading=false;$('#refresh').disabled=false;render()}}
}
function isFavorite(type,id){return prefs.favorites.some(x=>x.key===favoriteKey(type,id,prefs.committee))}
function star(type,id,title){if(!id)return '';return `<button class="star ${isFavorite(type,id)?'selected':''}" data-fav-type="${e(type)}" data-fav-id="${e(id)}" data-fav-title="${e(title)}" aria-pressed="${isFavorite(type,id)}" aria-label="Preferito: ${e(title)}">${isFavorite(type,id)?'★':'☆'}</button>`}
function matchCard(m){const live=Number(m.is_live)===1;const scored=Boolean(Number(m.played))||live||Number(m['team1-setwin'])>0||Number(m['team2-setwin'])>0;const pts=Array.isArray(m.pt_a)?m.pt_a.map((v,i)=>`${v}–${m.pt_b?.[i]??'–'}`).join(' · '):'';return `<article class="match"><div class="match-meta"><span>${e(m.date||'Data da definire')} · ${e(m.time||'')} ${m.ng?' / Gara '+e(m.ng):''}</span><span class="badge ${live?'live':''}">${live?'● In corso':scored?'Terminata':'In programma'}</span></div>${[m.team1,m.team2].map((t,i)=>`<div class="team-row"><span class="team-avatar" aria-hidden="true">${e(t?.title?.slice(0,2)||'V')}</span><strong>${e(t?.title||'Squadra da definire')}</strong>${star('team',t?.id,t?.title)}<span class="team-score">${scored?e(m[`team${i+1}-setwin`]??0):'–'}</span></div>`).join('')}<div class="match-bottom"><span>${e(m.stadium||'Impianto da definire')}</span><span class="sets">${e(pts)}</span></div></article>`}
function render(){
 $('#fav-count').textContent=prefs.favorites.length;
 if(tab==='favorites'){const favs=prefs.favorites.filter(x=>(!prefs.committee||x.committee===prefs.committee)&&x.title.toLocaleLowerCase('it').includes(query));$('#updated').textContent='Salvati su questo dispositivo';$('#results').innerHTML=favs.length?favs.map(f=>`<article class="saved"><strong><small>${f.type==='team'?'SQUADRA':'GIRONE'}</small>${e(f.title)}</strong>${f.type==='group'?`<button data-open-group="${e(f.id)}" data-committee="${e(f.committee)}">Apri ↗</button>`:''}<button data-remove="${e(f.key)}" aria-label="Rimuovi ${e(f.title)}">×</button></article>`).join(''):empty('Il tuo posto in prima fila','Tocca la stella accanto a una squadra o un girone per ritrovarli qui.');bindCards();return}
 if(!prefs.committee){$('#updated').textContent='';$('#results').innerHTML=empty('Da dove cominciamo?','Scegli il tuo comitato per seguire risultati, calendario e classifiche.');return}
 $('#updated').textContent=record?`${record.source==='import'?'Importati':record.source==='network'&&!record.fromCache?'Ricevuti':'Salvati'} · ${new Date(record.at).toLocaleString('it-IT',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}`:'';
 if(!record){$('#results').innerHTML=empty('Il campo è ancora vuoto','Nessun dato disponibile sul dispositivo. Prova ad aggiornare oppure importa un file JSON FIPAV.','<button id="empty-import">Importa dati</button>');$('#empty-import').onclick=openHelp;return}
 if(tab==='standings'){
 const d=payload(record.json),teams=d?.teams||[];const rows=teams.filter(t=>(t.title||t.squadra||t.nome_squadra||'').toLocaleLowerCase('it').includes(query));$('#results').innerHTML=teams.length?`${groupHeading(prefs.group,d.title||d.descrizione||'Classifica')}<div class="table-scroll"><table><caption class="skip">Classifica del girone</caption><thead><tr>${['Pos.','Squadra','Punti','G','V','P','SV','SP'].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map((t,i)=>`<tr><td>${e(t.pos??i+1)}</td><td>${star('team',t.id,t.title||t.squadra||t.nome_squadra)}${e(t.title||t.squadra||t.nome_squadra)}</td>${['p','g','gv','gp','sv','sp'].map(k=>`<td>${e(t[k]??0)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="fine">G: gare · V: vinte · P: perse · SV / SP: set vinti / persi</p>`:empty('Classifica non pubblicata','Non ci sono squadre nella risposta ricevuta.');bindCards();return}
 const all=matches(record.json);const list=all.filter(m=>(!date||dateISO(m)===date)&&(!query||`${m.team1?.title} ${m.team2?.title} ${m.groupTitle}`.toLocaleLowerCase('it').includes(query))&&(filter!=='live'||Number(m.is_live)===1)&&(filter!=='favorites'||isFavorite('group',m.groupId)||isFavorite('team',m.team1?.id)||isFavorite('team',m.team2?.id)));
 const map=new Map();for(const m of list){const key=m.groupId||'games';if(!map.has(key))map.set(key,[]);map.get(key).push(m)}
 $('#results').innerHTML=list.length?[...map].map(([id,ms])=>groupHeading(id,ms[0].groupTitle||'Gare')+ms.map(matchCard).join('')).join(''):empty('Nessuna gara in questa selezione','Prova a cambiare data, ricerca o filtro.');bindCards();
}
function groupHeading(id,title){return `<div class="group-heading">${e(title)}${star('group',id,title)}</div>`}
function bindCards(){document.querySelectorAll('[data-fav-id]').forEach(b=>b.onclick=()=>{const key=favoriteKey(b.dataset.favType,b.dataset.favId,prefs.committee);if(isFavorite(b.dataset.favType,b.dataset.favId))prefs.favorites=prefs.favorites.filter(x=>x.key!==key);else prefs.favorites.push({key,type:b.dataset.favType,id:b.dataset.favId,title:b.dataset.favTitle,committee:prefs.committee});savePrefs();render()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{prefs.favorites=prefs.favorites.filter(x=>x.key!==b.dataset.remove);savePrefs();render()});document.querySelectorAll('[data-open-group]').forEach(b=>b.onclick=()=>{prefs.committee=b.dataset.committee;prefs.group=b.dataset.openGroup;$('#committee').value=prefs.committee;savePrefs();switchTab('calendar')})}
function switchTab(next){tab=next;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});load()}
function openHelp(){const kinds=prefs.group?['live','groups','calendar','standings']:['live','groups'];$('#source-links').innerHTML=prefs.committee?kinds.flatMap(k=>urls(k,prefs.committee,prefs.group).map((url,i)=>`<a href="${e(url)}" target="_blank" rel="noopener">Apri JSON ${e({live:'risultati',groups:'gironi',calendar:'calendario',standings:'classifica'}[k])}${i?' (API)':''} ↗</a>`)).join(''):'<p>Seleziona un comitato per aprire le sorgenti JSON.</p>';$('#help').showModal()}
$('#committee').onchange=()=>{prefs.committee=$('#committee').value;prefs.group='';groups=[];savePrefs();load()};$('#group').onchange=()=>{prefs.group=$('#group').value;savePrefs();load()};
$('#refresh').onclick=load;$('#info').onclick=openHelp;$('#search').oninput=ev=>{query=ev.target.value.toLocaleLowerCase('it').trim();render()};$('#date').value=date;$('#date').onchange=ev=>{date=ev.target.value;render()};$('#all-dates').onclick=()=>{date='';$('#date').value='';render()};
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>switchTab(b.dataset.tab);
for(const b of document.querySelectorAll('[data-filter]'))b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()};
$('#import').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Il file supera il limite di 8 MB.');if(!prefs.committee)throw new Error('Seleziona prima il comitato.');const json=JSON.parse(await file.text());const kind=classify(json);const d=payload(json);const cid=d?.['commettee-id']||d?.commettees?.['my-commettee']?.id;if(cid&&String(cid)!==prefs.committee)throw new Error('Il file appartiene a un altro comitato. Seleziona il comitato corretto prima di importare.');if(kind==='calendar'||kind==='standings'){const id=String(d.id||prefs.group||'');if(!/^\d+$/.test(id))throw new Error('Seleziona il girone prima di importare questo file.');prefs.group=id;const saved=read(cacheKey('groups'),null)?.json?.data||[];if(!saved.some(g=>String(g.id)===id)){saved.push({type:'Calendar',id,title:d.title||d.descrizione||`Girone ${id}`});write(cacheKey('groups'),{json:{data:saved},at:Date.now(),source:'import'})}}
 const rec={json,at:Date.now(),source:'import'};if(!write(cacheKey(kind),rec))throw new Error('Memoria locale insufficiente.');savePrefs();$('#import-status').textContent='Dati importati e salvati sul dispositivo.';if(kind==='groups'){groups=json.data;updateGroups();if(!prefs.group&&groups[0]){prefs.group=String(groups[0].id);savePrefs()}switchTab('calendar')}else{switchTab(kind);date='';$('#date').value='';render()}$('#help').close();}catch(err){$('#import-status').textContent=err.message}finally{ev.target.value=''}};
$('#export').onclick=()=>{const data={preferences:prefs,cache:{}};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith('vl-data:'))data.cache[k]=read(k,null)}const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='volley-live-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
let installEvent;window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installEvent=ev;$('#install').hidden=false});$('#install').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null;$('#install').hidden=true}};window.addEventListener('appinstalled',()=>$('#install').hidden=true);
window.addEventListener('online',()=>{setConnection();load()});window.addEventListener('offline',setConnection);document.addEventListener('visibilitychange',()=>{if(!document.hidden)load()});setInterval(()=>{if(!document.hidden&&!loading&&tab!=='favorites'&&prefs.committee)load()},60000);
$('#today').textContent=new Intl.DateTimeFormat('it-IT',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()).toUpperCase();setConnection();
try{const r=await fetch('./committees.json');if(!r.ok)throw Error();const list=await r.json();const regions=[...new Set(list.map(c=>c.region))];$('#committee').innerHTML='<option value="">Scegli un comitato</option>'+regions.map(region=>`<optgroup label="${e(region)}">${list.filter(c=>c.region===region).map(c=>`<option value="${e(c.id)}">${e(c.title)}</option>`).join('')}</optgroup>`).join('');$('#committee').value=prefs.committee}catch{message('Elenco comitati non disponibile. Riapri l’app quando sei online.')}load();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>message('Il salvataggio offline dell’app non è disponibile in questo browser.'));
